  const vote = async (id:number,value:number) => {if(!requireUser() || !user) return; const old=votes[id] ?? 0; const next=old===value?0:value; setVotes({...votes,[id]:next}); const result = next ? await supabase.from('post_votes').upsert({user_id:user.id,post_id:id,value:next}) : await supabase.from('post_votes').delete().eq('user_id',user.id).eq('post_id',id); if(result.error) {setVotes({...votes,[id]:old}); setNotice(result.error.message);} else await loadPosts(); };
  const bookmark = async (id:number) => {if(!requireUser() || !user) return; const was=bookmarks.includes(id); setBookmarks(was?bookmarks.filter(x=>x!==id):[...bookmarks,id]); const result=was?await supabase.from('bookmarks').delete().eq('user_id',user.id).eq('post_id',id):await supabase.from('bookmarks').insert({user_id:user.id,post_id:id}); if(result.error){setBookmarks(bookmarks);setNotice(result.error.message);} };
