  const publishPost=async()=>{if(!user||!draft.title.trim())return;setBusy(true);let media_url:string|null=null;if(photo){media_url=await uploadMedia(photo,user.id,'post');if(!media_url){setBusy(false);return;}}const {error}=await supabase.from('posts').insert({media_url,author_id:user.id,handle:profile?.handle ?? (user.email?.split('@')[0] || 'student'),campus:profile?.campus??draft.campus,flair:draft.flair,title:draft.title.trim(),body:draft.body.trim(),kind:media_url?(photo?.type.startsWith('video/')?'upload-video':'photo'):'text'});setBusy(false);if(error)setNotice(error.message);else {pickPhoto(null);setDraft({title:'',body:'',campus:profile?.campus??'UNILAG',flair:'Campus'});setOverlay(null);setTab('home');setSort('new');await loadPosts();}};
