  const renderHeader=()=> <div className="kampus-header"><div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-3"><div className="min-w-0">{tab==='home'?<div className="flex items-center gap-2 text-xl font-extrabold"><img src="/favicon.svg" alt="" className="h-6 w-6" style={{height:24,width:24}}/>Chactive<span className="text-primary">.</span></div>:<h1 className="truncate text-[22px] font-extrabold">{tab==='anonymous'?'Anonymous':tab.charAt(0).toUpperCase()+tab.slice(1)}</h1>}</div><div className="flex shrink-0 items-center gap-2">{tab==='home' && !user && <><Button size="sm" variant="secondary" className="rounded-full" onClick={()=>{setAuthMode('login');setOverlay('auth');}}>Log in</Button><Button size="sm" className="rounded-full" onClick={()=>{setAuthMode('signup');setOverlay('auth');}}>Sign up</Button></>}{tab==='home' && user && <><Button variant="ghost" size="icon" title="Search" aria-label="Search" onClick={startSearch}><Search size={21}/></Button><Button variant="ghost" size="icon" title="Write a post" aria-label="Write a post" onClick={openCompose}><Plus size={22}/></Button></>}</div></div>{tab==='home' && <Tabs items={['best','hot','new','top']} value={sort} change={setSort}/>}</div>;
